import sys

def main():
    lines = sys.stdin.read().strip().splitlines()
    if not lines:
        print("-1 -1")
        return
    arr = list(map(int, lines[0].split()))
    target = int(lines[1].strip()) if len(lines) > 1 else None
    if not arr:
        print("-1 -1")
        return
    # find first occurrence
    lo, hi = 0, len(arr) - 1
    first = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] < target:
            lo = mid + 1
        elif arr[mid] > target:
            hi = mid - 1
        else:
            first = mid
            hi = mid - 1
    if first == -1:
        print("-1 -1")
        return
    # find last occurrence
    lo, hi = first, len(arr) - 1
    last = first
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] > target:
            hi = mid - 1
        else:
            last = mid
            lo = mid + 1
    print(f"{first} {last}")

if __name__ == "__main__":
    main()
